function constructRectangle(area) {
  // Look at every divisor pair and keep the one with the smallest gap.
  let best = null;
  for (let L = 1; L <= area; L++) {
    if (area % L !== 0) continue;
    const W = area / L;
    if (W > L) continue;
    if (best === null || L - W < best[0] - best[1]) best = [L, W];
  }
  return best;
}

