function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const max = size === 'large' ? 10000000 : 3000;
  const root = Math.floor(Math.sqrt(max));
  const roll = rand();
  // Perfect squares, products of two nearby numbers, and plain random values.
  if (roll < 0.2) {
    const side = int(1, root);
    return [side * side];
  }
  if (roll < 0.5) {
    const a = int(Math.max(1, root - 40), root);
    const b = int(a, Math.floor(max / a));
    return [a * b];
  }
  if (roll < 0.6) return [int(1, 12)];
  return [int(1, max)];
}
